184	            background-color: rgba(255, 255, 255, 0.12);
185	        }
186	
187	        header nav li a:hover::after {
188	            width: 100%;
189	        }
190	
191	        header nav li a:focus-visible {
192	            outline: 2px solid white;
193	            outline-offset: 4px;
194	            background-color: rgba(255, 255, 255, 0.15);
195	        }
196	
197	        main {
198	            max-width: 1200px;
199	            margin: 0 auto;
200	            padding: 40px 20px;
201	        }
202	
203	        article {
204	            margin-bottom: 3rem;
205	        }
206	
207	        h2 {
208	            color: var(--primary-color);
209	            margin-bottom: 1rem;
210	            font-size: 1.8rem;
211	        }
212	
213	        p {
214	            margin-bottom: 1rem;
