219	        .cta-button {
220	            display: inline-flex;
221	            align-items: center;
222	            justify-content: center;
223	            gap: 0.5rem;
224	            background: var(--primary-gradient);
225	            color: white;
226	            padding: 0.875rem 2rem;
227	            border: none;
228	            border-radius: 8px;
229	            font-size: 1rem;
230	            font-weight: 600;
231	            cursor: pointer;
232	            text-decoration: none;
233	            transition: all 0.3s ease;
234	            box-shadow: 0 4px 12px rgba(102, 126, 234, 0.3);
235	            position: relative;
236	            overflow: hidden;
237	            min-height: 44px;
238	            min-width: 44px;
239	            letter-spacing: 0.5px;
240	        }
241	
242	        .cta-button:hover:not(:disabled) {
